algorithms.pseudocode:
function IsCertificate(A, q):
    chi <- CharPoly(A)                # det(tI - A), degree n
    return IsIrreducible(chi, q)

function IsIrreducible(f, q):          # Rabin's test, deg f = n
    if n <= 0: return false
    if n == 1: return true
    if x^(q^n) != x (mod f): return false
    for each prime l dividing n:
        if gcd(x^(q^(n/l)) - x, f) != 1: return false
    return true
